local UIFeelingCommunicationTopicNode = Class("UIFeelingCommunicationTopicNode")
function UIFeelingCommunicationTopicNode:__init() 
    self._curTopicId = nil
    self._index = nil
    self._clickCb = nil
    self._co = nil
end

function UIFeelingCommunicationTopicNode:__delete()
    self._curTopicId = nil
    self._index = nil
    self._clickCb = nil
    self._co = nil
end

function UIFeelingCommunicationTopicNode:Awake()
    SetButtonAction(self.Btn, Bind(self, self.OnSelectCat))
end

function UIFeelingCommunicationTopicNode:Start()
end

function UIFeelingCommunicationTopicNode:Refresh(id, clickCb, index)
    self._curTopicId = id
    self._index = checkNumber(index)
    self._clickCb = clickCb
    local vo = PhoneUtils.GetPhoneTalkContentVo(id)
    if vo then
        CfUtils.FillText(self.Name, vo.name)
        CfUtils.FillText(self.Text, PhoneUtils.GetTalkContentSourceName(id))
        --CfUtils.FillImage(self.ImgTitle, PhoneUtils.GetTalkContentSourceImg(id)) 
        local switchImage = self.ImgTitle:GetComponent(typeof(UISwitchImage))
        switchImage.Status = checkNumber(vo.source)
    end
    self:RefreshUnSelect()

    local redGo = GameUtils.GetRedPointGo(self.Root)
    if redGo then
        if PhoneUtils.IsTalkCountIsNew(id) then
            KTool.SetActive(redGo, true)
        else
            KTool.SetActive(redGo, false)
        end
    end

    KTool.SetActive(self.Root, true)
    self:PlayAnimator()
end

--刷新选中状态
function UIFeelingCommunicationTopicNode:RefreshSelect()
    KTool.SetActive(self.Select, true)
    KTool.SetActive(self.Black, true)
end

--刷新未选中状态
function UIFeelingCommunicationTopicNode:RefreshUnSelect()
    KTool.SetActive(self.Select, false)
    KTool.SetActive(self.Black, false)
end

--播放动画
function UIFeelingCommunicationTopicNode:PlayAnimator()
    local ani = self.Root:GetComponent(typeof(Animator))
    self._co = cs_coroutine.start(function()
        coroutine.yield(WaitForSeconds(0.1 * self._index))
        ani:Play("FeelingCommunicationDialogCellMove")
    end)
end

function UIFeelingCommunicationTopicNode:OnSelectCat()
    if self._clickCb then
        self._clickCb()
    end
end

function UIFeelingCommunicationTopicNode:OnDestroy()
    if self._co then 
        cs_coroutine.stop(self._co)
        self._co = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFeelingCommunicationTopicNode
